"""Label styles of art run 7, agent C (arrange, teammark). Read from the Japanese lettering by
run7/C/c7_lib.py; every style is crisp (solid rings, fill ramps only). _s = small plates (one ring)."""
import numpy as np
from ui_styles_ore_ini import ringfill

STYLES = {}

def _sil(front, c):
    def style(ink, base):
        out, b = STYLES[front](ink, base)
        return np.where(out > 0, c, 0).astype(np.uint8), b
    return style

STYLES["c7_s3_s_02"] = ringfill([15, 15, 15, 1, 15, 15], [1], [])
STYLES["c7_s3_s_02L"] = ringfill([1, 1, 1, 1, 1, 1], [0], [])
STYLES["c7_s3_s_02L_s"] = ringfill([1, 1, 1, 1, 1, 1], [0], [])
STYLES["c7_s3_s_02_s"] = ringfill([15, 15, 15, 1, 15, 15], [1], [])
STYLES["c7_s3_s_13"] = ringfill([1, 9, 5, 5, 8, 5], [14], [14])
STYLES["c7_s3_s_13_p"] = ringfill([1, 1, 1, 1, 1, 1], [0], [])
STYLES["c7_s3_s_13_p_s"] = ringfill([1, 1, 1, 1, 1, 1], [0], [])
STYLES["c7_s3_s_13_s"] = ringfill([1, 9, 5, 5, 8, 5], [14], [])

def _win(front, c0, c1):
    def cut(ink, b):
        art, bb = STYLES[front](ink, b)
        out = art[:, c0:c1]
        if out.shape[1] == 0:
            out = np.zeros((art.shape[0], 1), np.uint8)
        return out, bb
    return cut

STYLES["c7_s3_s_13_p~0_86"] = _win("c7_s3_s_13_p", 0, 86)
STYLES["c7_s3_s_13_p~86_212"] = _win("c7_s3_s_13_p", 86, 212)

# whole-picture styles (the page picture with the Japanese cleared and the English set in it)
def _pic(comp, c0, c1, box, dy, front):
    comp = np.array(comp, np.uint8)
    bx0, by0, bx1, by1 = box
    def style(ink, base):
        art, _ = STYLES[front](ink, base)
        h, w = art.shape
        out = comp.copy()
        ox = bx0 + (bx1 - bx0 - w) // 2; oy = by0 + (by1 - by0 - h) // 2 + dy
        m = art > 0
        out[oy:oy + h, ox:ox + w][m] = art[m]
        return out[:, c0:c1], 0
    return style
